--
-- Table structure for table `assignments`
--

DROP TABLE IF EXISTS `assignments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `assignments` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `asset_id` int(11) NOT NULL,
  `assigned_to` int(11) DEFAULT NULL,
  `assigned_by` int(11) NOT NULL,
  `status` varchar(100) DEFAULT 'active',
  `notes` text DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `assigned_to_type` varchar(30) NOT NULL DEFAULT 'user',
  `assigned_to_id` int(11) DEFAULT NULL,
  `workflow_status` varchar(30) NOT NULL DEFAULT 'assigned',
  `assigned_date` datetime DEFAULT NULL,
  `expected_return_date` datetime DEFAULT NULL,
  `returned_at` datetime DEFAULT NULL,
  `department_id` int(11) DEFAULT NULL,
  `location` varchar(255) DEFAULT NULL,
  `condition_at_assignment` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `assignments_status_created_at_idx` (`status`,`created_at`),
  KEY `assignments_type_created_at_idx` (`assigned_to_type`,`created_at`),
  KEY `assignments_department_date_idx` (`department_id`,`assigned_date`),
  KEY `assignments_expected_return_idx` (`expected_return_date`)
) ENGINE=InnoDB AUTO_INCREMENT=158 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

